//! owning callback position. Source expressions still denote the Closure.
use super::*;

impl Builder<'_, '_> {
    pub(crate) fn closure_slot(
        &mut self,
        name: &str,
        id: ClosureId,
        value: ValueId,
        span: Span,
    ) -> R<()> {
        let element = Type::Closure(id);
        self.check_owned_array_closure(&element, 1, span)?;
        let storage = Type::Array {
            element: Box::new(element),
            length: 1,
        };
        let value = self.value(
            InstructionKind::MakeOwnedArray {
                elements: vec![value],
            },
            storage.clone(),
            span,
        )?;
        let local = self.local(name, storage, true, span)?;
        self.store(local, value, span)?;
        self.closure_slots.insert(local, id);
        Ok(())
    }

    pub(crate) fn take_closure_slot(&mut self, local: LocalId, span: Span) -> R<(ValueId, Type)> {
        let ty = Type::Closure(self.closure_slots[&local]);
        let value = self.value(
            InstructionKind::TakeOwnedArrayElement { local, index: 0 },
            ty.clone(),
            span,
        )?;
        Ok((value, ty))
    }

    pub(crate) fn borrow_closure_slot(
        &mut self,
        local: LocalId,
        mutable: bool,
        span: Span,
    ) -> R<(ValueId, Type)> {
        let ty = Type::Address {
            mutable,
            inner: Box::new(Type::Closure(self.closure_slots[&local])),
        };
        let value = self.value(
            InstructionKind::BorrowOwnedArrayElement {
                local,
                index: 0,
                mutable,
            },
            ty.clone(),
            span,
        )?;
        Ok((value, ty))
    }

    pub(crate) fn assign_closure_slot(
        &mut self,
        local: LocalId,
        rhs: &CoreExpr,
        span: Span,
    ) -> R<()> {
        let element = Type::Closure(self.closure_slots[&local]);
        let (value, actual) = self.owned_array_input(rhs, Some(&element))?;
        self.same(&actual, &element, rhs.span)?;
        // Keep the prepared value responsible if evaluation exits early, and
        // retain the existing lexical shell instead of retiring a whole owner.
        let prepared = self.stage_argument(value, &element, rhs.span)?;
        self.emit(
            InstructionKind::DropOwnedArrayElement { local, index: 0 },
            None,
            span,
        )?;
        let value = self.commit_arguments(vec![prepared], rhs.span)?[0];
        self.emit(
            InstructionKind::StoreOwnedArrayElement {
                local,
                index: 0,
                value,
            },
            None,
            span,
        )?;
        Ok(())
    }
}

pub(super) fn package_assign(&mut self, target: &CoreExpr, rhs: &CoreExpr) -> R<bool> {
    if self.owned_array_assign(target, rhs)? {
        return Ok(true);
    }
    let Some((local, index, ty)) = self.package_place(target)? else {
        return Ok(false);
    };
    if !self.function.locals[local.0 as usize].mutable {
        return Err(error(
            "E-IMMUTABLE-ASSIGNMENT",
            target.span,
            "package field assignment requires a mutable local shell",
        ));
    }
    // Resolve the static local and field before evaluating RHS. A real
    // temporary holds its new obligation until old-field cleanup commits.
    let (value, actual) = if matches!(ty, Type::Closure(_)) {
        self.check_owned_array_closure(&ty, 1, rhs.span)?;
        self.owned_array_input(rhs, Some(&ty))?
    } else {
        self.transfer_expr(rhs, Some(&ty))?
    };
    self.same(&actual, &ty, rhs.span)?;
    let value = if matches!(
        ty,
        Type::Managed(_) | Type::Closure(_) | Type::Package { .. }
    ) || array_field_supported(&ty)
    {
        let prepared = self.stage_argument(value, &ty, rhs.span)?;
        self.emit(
            InstructionKind::DropPackageField { local, index },
            None,
            target.span,
        )?;
        self.commit_arguments(vec![prepared], rhs.span)?[0]
    } else {
        value
    };
    self.emit(
        InstructionKind::StorePackageField {
            local,
            index,
            value,
        },
        None,
        target.span,
    )?;
    Ok(true)
}

